import {signs,planetData,type Sign} from './data';
import {type Position,type Aspect,zodiac,degree} from './astro';
export type SignDepth={motivation:string;relationships:string;friendship:string;care:string;creation:string;growth:string;example:string;placements:Record<string,string>};
export const signDepth:Record<string,SignDepth>={
Aries:{motivation:'Aries is cardinal fire: the initiating movement of the fire element. Its central question is “What happens if I begin?” In a chart, Aries can describe a willingness to discover through action before every detail is known. This is distinct from being constantly confident; courage can coexist with uncertainty. Mars gives this sign a vocabulary of choice, boundaries, assertion, and the energy required to separate from what came before.',relationships:'Interest is often expressed through initiative: an invitation, a direct compliment, or making a plan. A relationship has room to breathe when both people retain interests of their own. Excitement can be mistaken for compatibility, so consistency matters after the first spark. During conflict, a clear request and a chance to cool down may work better than prolonged guessing.',friendship:'Shared activities can make friendship feel alive: trying a new trail, starting a project, or encouraging a friend to take a first step. The gift is advocacy and willingness to show up in a difficult moment. A useful adjustment is asking whether a friend wants encouragement, practical action, or simply someone to listen.',care:'Autonomy can be emotionally important even when closeness is deeply wanted. A direct invitation to choose may feel more caring than having a solution imposed. Anger can sometimes be the first visible signal of disappointment or vulnerability. Pause long enough to name the feeling beneath the impulse.',creation:'Aries often creates through experimentation and prototypes. Work feels engaging when decisions can lead to visible action, and when there is enough freedom to test an idea. Finishing repetitive stages may require deliberately designed support: a deadline, a partner, or a smaller next step. Leadership can mean opening a door rather than always staying in front.',growth:'Assertiveness becomes more effective when it includes awareness of impact. The growth task is to distinguish urgency from importance and independence from isolation. A pause need not extinguish enthusiasm; it can give desire a better direction.',example:'At a meeting with no clear next step, Aries symbolism might look like volunteering a first draft. Its mature expression also asks who needs to be included before that draft becomes a decision.',placements:{Sun:'Identity develops through initiative, agency, and discovering what is worth standing for. Being first can be less important than acting with personal conviction.',Moon:'Emotional processing may be quick and immediate. Space to move, make a choice, or state a feeling directly can help; a fast reaction does not necessarily describe the lasting feeling.',Ascendant:'New situations may be met directly, with an instinct to engage and find out through experience. Follow Mars, the traditional chart ruler, to its sign and house to see where that initiating approach is concentrated.',Mercury:'Thinking may be fast, decisive, and interested in the central point. Try leaving room for a second perspective before treating an initial conclusion as the final one.',Venus:'Affection may be candid, playful, and energized by mutual pursuit. Clear interest and the freedom to remain an individual can matter more than elaborate signals.',Mars:'Mars is in its traditional domicile here. Action can be straightforward and self-directed; the constructive question is how to direct force consistently without making every disagreement a contest.'}},
Taurus:{motivation:'Taurus is fixed earth: sustained attention to what has value and can be built, grown, or enjoyed. Its question is “What is worth keeping?” This can describe material resources, but also time, trust, craft, and the sensory experience of being alive. Venus rulership adds appreciation, reciprocity, and the ability to cultivate rather than continually replace.',relationships:'Trust may grow through repeated, ordinary acts: keeping an arrangement, making food, or remembering a preference. Security is strongest when reliability includes the ability to talk about changing needs. Loyalty can be a gift without becoming an obligation to remain in an arrangement that no longer works.',friendship:'A durable friendship may take shape through shared routines and practical support. Taurus symbolism often values a person who does what they said they would do. Making occasional room for a new experience keeps comfort from narrowing the friendship.',care:'An unhurried environment, familiar sensory comforts, and consistency can make it easier to identify a feeling. Sudden pressure may lead to resistance before the underlying need is understood. Offer a manageable transition and enough information to make an informed choice.',creation:'This sign can describe patient development of a tangible form: a garden, a meal, a financial plan, a piece of music, or an object made with care. Work preferences often include time to build skill and standards that are stable enough to trust. Creativity can be incremental and still be original.',growth:'Distinguish grounded commitment from remaining still because a change is uncomfortable. A useful question is whether a routine continues to support the values it was created to serve. Change can happen through small, repeatable steps rather than a total upheaval.',example:'A Taurus expression might spend several weekends refining one ceramic bowl, learning from its weight, texture, and balance rather than seeking a different idea every day.',placements:{Sun:'Identity may organize around personal values, self-possession, and the satisfaction of cultivating something real. Ask which commitments are chosen rather than simply familiar.',Moon:'The Moon is traditionally exalted in Taurus. Emotional steadiness may be supported by predictable care, physical comfort, and time to settle; this does not mean difficult feelings never arise.',Ascendant:'You may approach the unfamiliar by observing its pace and practical conditions first. Follow Venus to its sign, house, and aspects for a fuller account of this approach.',Mercury:'Thinking may be deliberate, concrete, and strengthened by examples that can be observed or tested. Being given time to consider can be more useful than being pressed for an immediate reply.',Venus:'Venus is in its traditional domicile here. Affection can be expressed through consistency, shared pleasures, touch where welcome, and the care taken over an ordinary moment.',Mars:'Action may gather slowly and continue for a long time. Mars is traditionally in detriment here; desire may need to negotiate between preserving comfort and making a decisive change, rather than lacking strength.'}},
Gemini:{motivation:'Gemini is mutable air: movement through language, observation, and alternative perspectives. Its question is “What else could this mean?” Mercury rulership emphasizes exchange and the ability to translate between different people or ideas. Multiplicity can be a resource for understanding; it is not the same as having no convictions.',relationships:'Conversation and interest in the other person’s mind can be central ways of connecting. Variety helps when it is shared rather than used to avoid a difficult conversation. A useful distinction is between needing room to explore and leaving a partner unsure of an agreement.',friendship:'Friendship may grow through messages, humor, shared discoveries, and the freedom to resume a conversation after time apart. A curious question can communicate care. Listening without immediately supplying a different angle can make room for a friend’s emotional reality.',care:'Putting a feeling into words may be part of discovering what it is. Talking, writing, or asking questions can help, but analysis is not always a substitute for experiencing the feeling. It can be useful to ask, “Do I need more information, or do I need to sit with what I already know?”',creation:'Language, teaching, editing, interviewing, design, and connecting distant topics are natural fields for this symbolism. Work can be rewarding when there is variation within a clear frame. A project benefits from a place to collect new ideas without allowing every new idea to replace the current priority.',growth:'Practice giving an idea enough time to deepen after it is no longer novel. Intellectual flexibility works best alongside clear commitments and a willingness to say when an answer is not yet known.',example:'Gemini symbolism might turn a casual conversation with a neighbor into a community newsletter, noticing connections between people who had not met.',placements:{Sun:'Identity may develop through curiosity, communication, and the freedom to hold more than one perspective. A coherent self does not require the same interest every year.',Moon:'Emotional regulation may involve conversation, movement between activities, or a fresh perspective. Notice when a witty explanation helps and when it sidesteps a more vulnerable statement.',Ascendant:'An observant, questioning approach may shape first encounters. Mercury’s sign and house show where this instinct to connect and interpret is directed.',Mercury:'Mercury is in its traditional domicile here. Thinking may be quick, associative, and highly responsive to context; depth grows when the conversation is allowed to continue past the first interesting connection.',Venus:'Playfulness, mental rapport, and ongoing discovery can be important in affection. Agreements are clearer when curiosity is paired with direct discussion of expectations.',Mars:'Action may proceed through words, information, negotiation, or several parallel routes. Choose which argument or project deserves energy instead of answering every possible provocation.'}},
Cancer:{motivation:'Cancer is cardinal water: the initiative to protect, nurture, and create belonging. Its question is “What needs care here?” The Moon’s rulership gives this sign a connection to memory, cycles, and changing emotional conditions. Protectiveness can include the courage to create a new home or family pattern, rather than only preserving the past.',relationships:'Closeness may develop through remembering details, creating rituals, and making a relationship feel safe enough for less polished feelings. Familiarity supports trust, but another person cannot be expected to intuit every need. Naming a request helps distinguish present needs from old disappointments.',friendship:'Thoughtful check-ins, keeping memories, and offering a welcoming place can be important forms of friendship. Care works best when it is reciprocal and when helping does not become a way of avoiding one’s own needs.',care:'Feelings may arrive through association and memory, before they have a tidy explanation. A calm tone and a reliable response can matter as much as the words used. Privacy can be restorative, while prolonged withdrawal may make repair harder.',creation:'Cancer symbolism can work through food, photography, history, storytelling, interiors, and any practice that gives emotional experience a form. Work may feel meaningful when it serves people whose lives can be understood personally. Caring and professional boundaries can support one another.',growth:'Develop a boundary that protects without shutting out every unfamiliar experience. Ask whether a response belongs to the current situation or to a memory it resembles. Receiving care is as important as providing it.',example:'A Cancer expression might build a family recipe archive, recording not just ingredients but the people and occasions that gave the food meaning.',placements:{Sun:'Identity may grow through cultivating belonging, protecting what matters, and giving care a meaningful form. Your needs belong in the circle of care too.',Moon:'The Moon is in its traditional domicile here. Emotional memory and responsiveness may be pronounced; familiar rituals can support steadiness through changing moods.',Ascendant:'You may read the emotional atmosphere before deciding how much to reveal. Follow the Moon’s sign, house, and aspects to connect this protective approach with the rest of the chart.',Mercury:'Communication may be attentive to tone, context, and remembered experience. A direct question can help check an impression before it becomes an assumption.',Venus:'Affection may be expressed through consideration, continuity, and a sense of home. Talk about which gestures feel caring instead of assuming everyone receives care in the same way.',Mars:'Mars is traditionally in fall here. Action may be strongly tied to protection or emotional investment. The task is to state a boundary clearly before frustration has to speak indirectly.'}},
Leo:{motivation:'Leo is fixed fire: a sustained relationship with creative vitality, heartfelt expression, and the wish to contribute something personally meaningful. Its question is “What can I bring to life?” The Sun’s rulership gives Leo a symbolism of coherence and visibility. Wanting to be seen can mean wanting one’s care, creativity, or effort to be recognized—not simply wanting attention.',relationships:'Warmth, loyalty, play, and openly expressed affection can make connection feel generous. Leo symbolism often values being chosen wholeheartedly. A useful conversation distinguishes appreciation from constant reassurance: both people need room to have an ordinary day without performing enthusiasm.',friendship:'Encouragement can be a powerful gift: celebrating a friend’s work, making an occasion feel special, or helping someone feel less ashamed to be visible. Friendship becomes more reciprocal when encouragement also includes curiosity about experiences that do not mirror one’s own.',care:'Recognition may feel most nourishing when it is specific and sincere. “I noticed how carefully you handled that” can matter more than grand praise. During hurt, pride may make a direct request for comfort feel difficult. A warm response can help separate disappointment from the fear of being unimportant.',creation:'Performance is one expression, but so are teaching, organizing a celebration, mentoring, leadership, and making everyday work feel alive. Fixed fire can sustain a creative vision through repeated practice. A good work environment recognizes individual contribution while allowing collaboration and feedback to improve the result.',growth:'Practice sharing unfinished work and receiving a response without making it a referendum on personal worth. Generosity has more freedom when it does not require a particular audience reaction. Leadership can include letting another person’s contribution become central.',example:'A Leo expression might turn a routine team presentation into a clear, engaging story and make sure quieter contributors receive credit when the work is recognized.',placements:{Sun:'The Sun is in its traditional domicile here. Identity may be nourished by creative authorship, sincere affection, and acting from a recognizable personal center. Visibility is most satisfying when it serves something you care about.',Moon:'Emotional needs may include warmth, play, and knowing that one’s presence matters. Ask for a specific kind of acknowledgment rather than waiting for another person to guess what would feel reassuring.',Ascendant:'New situations may be met with expressive warmth or a wish to bring the room together. Follow the Sun, the chart ruler, to its sign, house, and aspects to see where that organizing energy finds a purpose.',Mercury:'Communication may be vivid, personal, and strengthened by a clear narrative. Stories can make an idea memorable; invite questions so that a compelling presentation also remains a conversation.',Venus:'Affection may be wholehearted and expressive, with pleasure in celebrating the people one loves. Mutual admiration works best when it includes ordinary kindness as well as special gestures.',Mars:'Action may be driven by pride in a creative goal and the desire to act with heart. Sustaining a vision is a strength; conflict becomes easier when disagreement is separated from disrespect.'}},
Virgo:{motivation:'Virgo is mutable earth: adapting practical methods to what a situation actually needs. Its question is “What would make this work better?” Mercury rulership emphasizes discrimination, craft, and useful attention. Precision can express care and curiosity; it need not be a demand for faultlessness.',relationships:'Reliability may appear through noticing small needs and making life easier. Practical help is most welcome when it is requested or offered without implying that the other person is a project to fix. Appreciation of effort can be more helpful than reassurance that nothing needs changing.',friendship:'A friend may experience Virgo symbolism as thoughtful follow-through: remembering an appointment, checking a detail, or helping solve a real problem. Leave room for enjoyment that has no practical outcome and for a friend to choose a solution different from your own.',care:'A manageable routine can create enough space to process feelings. When worried, the impulse may be to gather details or correct the environment. Ask which task actually matters and which feeling would remain even if every task were completed.',creation:'Editing, research, design, music practice, repair, analysis, and skilled craft can make discernment visible. Work benefits from clear scope and enough time to refine. Creativity can involve removing what is unnecessary until the useful or beautiful form is easier to see.',growth:'Separate self-worth from the usefulness of the latest contribution. A workable standard can be chosen deliberately rather than lowered reluctantly. Criticism becomes more constructive when it begins by identifying the shared aim.',example:'A Virgo expression might redesign a confusing form so that people make fewer mistakes, then test it with real users instead of assuming a neat layout is enough.',placements:{Sun:'Identity may develop through competence, discernment, and a meaningful contribution. Choose standards that serve the work rather than treating the work as proof of personal adequacy.',Moon:'Emotional steadiness may be supported by useful routines and a clear next step. Practical action can help, while feelings still deserve attention when there is no problem to solve.',Ascendant:'You may initially notice details, practical needs, and how a setting is organized. Mercury’s sign and house show where that observant approach is applied.',Mercury:'Mercury is traditionally both domiciled and exalted in Virgo. Language and thinking may be analytical and precise; the skill is to preserve clarity without demanding certainty where none is available.',Venus:'Venus is traditionally in fall here. Affection may be expressed through discernment, consideration, and practical service. Let pleasure and imperfection have a place alongside care and improvement.',Mars:'Action may be methodical, skillful, and aimed at a specific result. Frustration can gather around inefficiency; prioritize a useful change rather than responding to every flaw.'}},
Libra:{motivation:'Libra is cardinal air: the initiative to establish a relationship between perspectives. Its question is “How can we meet fairly?” Venus rulership brings an interest in proportion, reciprocity, and what makes a shared space livable. Harmony has substance when it includes honest differences, rather than simply keeping those differences out of view.',relationships:'Partnership may be a place of active discovery. Consideration, mutual decisions, and the ability to see the other person’s position can be gifts. A relationship needs access to personal preference as well: agreement is clearer when each person knows what the other actually wants.',friendship:'Libra symbolism can make room for people, introduce friends, and notice when someone is being excluded. The challenge is to avoid becoming the permanent mediator at the expense of having a position of one’s own.',care:'A respectful exchange can help a feeling become clearer. An aesthetically pleasant or peaceful setting may help, but a difficult truth still needs somewhere to go. Asking for time to decide can be more honest than agreeing and later resenting the agreement.',creation:'Design, music, diplomacy, writing dialogue, mediation, law, and collaborative practice can express a sensitivity to relationship and proportion. Work may benefit from thoughtful partners and explicit decision rules so that weighing alternatives can eventually produce action.',growth:'Practice naming a preference before negotiating it. Fairness need not mean equal amounts of everything; it can mean an agreement both people can genuinely support. Conflict handled with respect can deepen trust.',example:'A Libra expression might help two collaborators find a design direction that honors both aims, while also stating which parts of the proposal they personally believe are strongest.',placements:{Sun:'The Sun is traditionally in fall here. Identity may develop through relationship and perspective-taking; the task is to keep a personal center while remaining open to another person.',Moon:'Emotional steadiness may benefit from companionship and respectful dialogue. Make space for an inconvenient feeling before turning it into a balanced account of everyone’s needs.',Ascendant:'You may begin by seeking rapport, shared language, or a sense of proportion. Follow Venus to its sign, house, and aspects to understand the values guiding that approach.',Mercury:'Thinking may be comparative and attentive to how ideas will be received. A useful next step is to name a decision criterion when several options all have merit.',Venus:'Venus is in its traditional domicile here. Affection may be expressed through reciprocity, social grace, and shared appreciation. Mutuality becomes stronger through honest requests, not mind-reading.',Mars:'Mars is traditionally in detriment here. Action may involve negotiation, alliance, or a concern with fairness. Directness can coexist with tact; a boundary does not have to wait for unanimous approval.'}},
Scorpio:{motivation:'Scorpio is fixed water: sustained emotional attention, depth, and the instinct to recognize what is consequential. Its question is “What is really at stake?” Traditional Mars rulership emphasizes resolve, protection, and the ability to face difficulty. Modern Pluto rulership adds a vocabulary of power and transformation. These are different historical frameworks, not interchangeable astronomical facts.',relationships:'Trust may grow through emotional honesty, discretion, and consistent behavior when things are complicated. Intimacy does not require total access to another person’s inner life. Discussing privacy and boundaries directly can be more revealing than testing whether someone will prove loyalty.',friendship:'Scorpio symbolism can describe a friend willing to stay present for a difficult conversation and keep a confidence. Depth is strongest when there is also room for lightness and for another person to have connections outside the friendship.',care:'An experience may need time before it is ready to be shared. Privacy can help integrate a feeling; secrecy can sometimes make it harder to receive support. A reliable response to a small disclosure can build trust more effectively than a demand for complete openness.',creation:'Research, investigation, psychology, strategy, restoration, fiction, and art that explores hidden experience can fit this symbolism. Work may feel engaging when it has substance and requires sustained attention. A clear ethical boundary matters when working with sensitive information or unequal power.',growth:'Distinguish discernment from assuming that the worst interpretation is the deepest one. Vulnerability can include saying “I do not know” or making a direct request before gathering evidence against a possible disappointment.',example:'A Scorpio expression might follow a confusing research result until its underlying cause becomes clear, then explain the finding without using privileged information to control the conversation.',placements:{Sun:'Identity may deepen through honest engagement with complexity and the willingness to change a pattern that no longer serves. Intensity is most useful when it has a chosen purpose.',Moon:'The Moon is traditionally in fall here. Feelings may be private, concentrated, or strongly tied to trust. This describes a symbolic tension around vulnerability, not an inability to give or receive care.',Ascendant:'You may enter unfamiliar situations with close observation and a careful sense of what to reveal. Follow Mars as the traditional chart ruler; Pluto can add a clearly labeled modern perspective.',Mercury:'Thinking may be investigative, strategic, and interested in underlying motives. Check a compelling inference against evidence, especially when a conversation touches an old sensitivity.',Venus:'Venus is traditionally in detriment here. Connection may involve emotional depth, loyalty, and strong investment. Honest agreements around privacy, autonomy, and reassurance help intensity remain reciprocal.',Mars:'Mars is in its traditional domicile here. Action may be concentrated, persistent, and strategically timed. Directly naming an aim can keep patience from becoming an indirect contest for control.'}},
Sagittarius:{motivation:'Sagittarius is mutable fire: adapting through discovery, experience, and a wider horizon of meaning. Its question is “What could this teach me?” Jupiter rulership supports perspective and the wish to connect individual experiences to a larger story. Confidence can open a possibility, while curiosity helps keep a belief responsive to experience.',relationships:'Shared discovery, candor, and room to grow can enliven connection. Freedom becomes more trustworthy when commitments are discussed specifically rather than left broad enough to mean different things. Enthusiasm for a future plan benefits from attention to the other person’s current reality.',friendship:'Friendship may thrive through adventures, lively debate, teaching one another, or seeing a familiar place from a new angle. The gift is encouragement and perspective. Ask before turning a friend’s difficult moment into a lesson or a silver lining.',care:'Space, humor, and a renewed sense of possibility may support emotional processing. Optimism can be helpful without requiring every feeling to become positive immediately. Staying present with disappointment can make hope more durable.',creation:'Teaching, travel, publishing, philosophy, storytelling, outdoor pursuits, and cross-cultural work can give exploration a form. Good work structures preserve a sense of purpose while making responsibilities concrete. A broad vision becomes useful through selected, achievable steps.',growth:'Practice checking a general statement against the particular case. Candor works best with attention to timing and impact. A commitment can support freedom by making expectations clear enough that they do not need constant renegotiation.',example:'A Sagittarius expression might develop a travel essay that changes an earlier assumption, showing both excitement about discovery and willingness to revise the story.',placements:{Sun:'Identity may grow through exploration, purpose, and the confidence to test a larger possibility. Meaning becomes richer when experience is allowed to challenge an inherited belief.',Moon:'Emotional needs may include perspective, openness, and room to move. Ask whether a new horizon offers genuine renewal or simply postpones a feeling that needs attention.',Ascendant:'You may approach the unfamiliar as an invitation to discover. Jupiter’s sign, house, and aspects show where that expanding orientation meets concrete circumstances.',Mercury:'Mercury is traditionally in detriment here. Thinking may prioritize a larger pattern over fine distinctions. Preserve the useful big picture while checking the details on which it depends.',Venus:'Affection may be strengthened by honesty, shared interests, humor, and discovery. Talk about how independence and commitment can both be supported in daily life.',Mars:'Action may be energized by a goal, belief, journey, or cause. A clear ethical aim and a practical plan help enthusiasm continue after the first burst.'}},
Capricorn:{motivation:'Capricorn is cardinal earth: the initiative to give a long-term aim a workable structure. Its question is “What is worth building over time?” Saturn rulership adds awareness of limits, responsibility, and the effects of repeated choices. Competence can express care and commitment; it need not imply an absence of feeling.',relationships:'Trust may grow through dependability and the willingness to take a shared future seriously. A relationship also needs room for needs that are not efficiently solved. Offering a plan can be caring, while asking “Would you like help or company?” allows another form of closeness.',friendship:'Steady support, practical advice, and showing up when it matters can be important gifts. Friendship can also be a place where achievement is not being measured and humor need not have a productive purpose.',care:'Clear expectations can make vulnerability feel less risky. Feelings may be processed privately before they are expressed. Receiving help can be a significant form of trust, especially when being capable has become a familiar role.',creation:'Architecture, organization, stewardship, craft, administration, and long projects can express this sign’s sense of form and consequence. Work benefits from meaningful authority, realistic resources, and the opportunity to improve a system rather than merely endure it.',growth:'Distinguish responsibility from assuming that everything will fail unless you personally manage it. A sustainable plan includes rest and support. Limits can be acknowledged without turning them into a judgment about worth.',example:'A Capricorn expression might turn an ambitious community idea into a funded project, including maintenance and succession so that it can continue after the founder steps away.',placements:{Sun:'Identity may develop through responsibility, mastery, and building something with lasting usefulness. Recognition can matter, but a chosen standard is different from an endless need to prove adequacy.',Moon:'The Moon is traditionally in detriment here. Care may be expressed through reliability or restraint. Explicitly making room for softness helps practical strength remain emotionally available.',Ascendant:'You may initially assess the structure, expectations, and practical demands of a situation. Saturn’s placement shows where that measured approach finds its central work.',Mercury:'Thinking may be strategic, organized, and attentive to what an idea will require in practice. Ask whether a realistic concern is clarifying the plan or closing it down too early.',Venus:'Affection may be shown through commitment, reliability, and taking another person seriously. Enjoyment does not need to be earned by completing every responsibility first.',Mars:'Mars is traditionally exalted here. Action may benefit from discipline, timing, and the ability to work within constraints. Use a sustainable pace rather than treating endurance as the only measure of strength.'}},
Aquarius:{motivation:'Aquarius is fixed air: sustained attention to ideas, principles, networks, and possibilities beyond the familiar arrangement. Its question is “Could this be organized differently?” Traditional Saturn rulership emphasizes systems and commitments; modern Uranus rulership emphasizes innovation and disruption. Neither framework requires being detached from personal feeling.',relationships:'Friendship, intellectual rapport, and respect for individuality can be important foundations. Independence works best when another person also knows how to reach you emotionally. A principled account of the relationship can be enriched by a simple statement of what is being felt now.',friendship:'Groups, shared causes, unusual interests, and a willingness to make room for difference can bring people together. The gift is a wider sense of belonging. The challenge is to notice the individual person as carefully as the idea of community.',care:'Space to think and freedom from pressure to react in a prescribed way may help. Observing a feeling can create useful perspective, while continuing to analyze can sometimes postpone contact with it. A specific, non-demanding check-in may be easier to answer than a sweeping emotional question.',creation:'Technology, research, social design, experimental art, organizing networks, and questioning a system’s assumptions can express this symbolism. Work may be rewarding when it connects an original idea to a real collective need. A new structure still needs testing with the people affected.',growth:'Allow a principle to be informed by particular experience without treating that as abandoning the principle. Difference need not become a fixed identity that makes ordinary needs harder to admit.',example:'An Aquarius expression might design a cooperative tool and invite the community to change its rules after discovering how the first version affects different members.',placements:{Sun:'The Sun is traditionally in detriment here. Identity may develop through ideals, community, and the freedom to be distinct. A collective role need not replace access to personal wishes.',Moon:'Emotional needs may include autonomy, friendship, and room to process in an individual way. Naming one concrete feeling can help a thoughtful explanation become a point of contact.',Ascendant:'You may meet new situations by observing the wider system or questioning an assumption. Follow Saturn as the traditional chart ruler; Uranus can offer an additional modern perspective.',Mercury:'Thinking may be conceptual, inventive, and able to see a pattern from outside its usual frame. Translate the idea into a specific example so others can participate in testing it.',Venus:'Connection may be rooted in friendship, shared values, and respect for difference. Discuss what closeness looks like in practice rather than assuming autonomy has only one possible form.',Mars:'Action may be organized around an idea, a group, or a wish to change a system. Ask what concrete intervention will serve the principle, including how it affects individual people.'}},
Pisces:{motivation:'Pisces is mutable water: responsiveness to feeling, imagination, and the connections that do not fit neatly into categories. Its question is “What is being felt beyond the words?” Traditional Jupiter rulership emphasizes meaning and inclusion; modern Neptune rulership emphasizes imagination and permeability. Sensitivity can be a source of discernment when it is paired with clear boundaries.',relationships:'Empathy, shared imagination, gentleness, and the ability to make room for vulnerability can support intimacy. A feeling of connection is different from a clear agreement. Asking directly about expectations helps compassion coexist with mutual responsibility.',friendship:'Listening, creative companionship, and an ability to recognize another person’s experience can be gifts. Care is more sustainable when it does not require absorbing every difficulty or being available without limits.',care:'Quiet, music, art, solitude, or a gentle transition between activities may help make a feeling recognizable. An impression can be meaningful without being a fact about another person. Check what belongs to you, what has been communicated, and what is still uncertain.',creation:'Music, film, poetry, visual art, care, and imaginative storytelling can translate subtle experience into a shareable form. Work benefits from protected creative space and a practical container: a clear brief, a deadline, or a routine that makes it possible to begin.',growth:'Practice a kind, specific boundary before exhaustion makes withdrawal the only apparent choice. A dream can be respected by giving it a next step, and compassion can include asking another person to take responsibility for their own part.',example:'A Pisces expression might turn an elusive feeling into a short film, then use a careful production schedule to give the imagined world a finished form.',placements:{Sun:'Identity may develop through imagination, compassion, and a sense of connection beyond a narrowly defined role. A clear choice about where to give energy helps that openness take form.',Moon:'Feelings may be receptive to atmosphere and difficult to separate from surrounding experience. Gentle rituals and explicit boundaries can help distinguish care from emotional overextension.',Ascendant:'You may approach the unfamiliar through impression, empathy, or imagination. Follow Jupiter as the traditional chart ruler; Neptune offers an additional modern interpretive lens.',Mercury:'Mercury is traditionally in detriment and fall here. Thinking may be associative, visual, or intuitive rather than linear. Use notes, examples, or a clear recap when precision matters.',Venus:'Venus is traditionally exalted here. Affection may be compassionate and imaginative. Let appreciation of possibility remain connected to how the relationship is actually being lived.',Mars:'Action may be indirect, imaginative, or motivated by care and meaning. Define a manageable next step and a boundary so that energy is not dispersed across every possible need.'}}
};
export type PlanetDepth={function:string;question:string;practice:string;cycle:string;retro:string;relationship:string;work:string};
export const planetDepth:Record<string,PlanetDepth>={
Sun:{function:'identity, creative purpose, and the capacity to organize life around a personal center',question:'Where do I want to act with greater authorship?',practice:'Choose one small project whose direction you can own. Notice the difference between recognition that supports the work and recognition that has become the work.',cycle:'The Sun travels through the zodiac in about one year, moving close to one degree per day. A solar return is the moment it reaches the natal longitude again, not simply midnight on a birthday.',retro:'The geocentric Sun does not retrograde. Atlas never assigns a retrograde label to this luminary.',relationship:'The Sun can describe a need for recognition and the style in which a person seeks to contribute. In synastry, compare how each person’s sense of purpose meets the other’s emotional patterns, values, and limits.',work:'The Sun can be useful when reflecting on authorship, visibility, creative commitment, and what makes a role feel personally meaningful.'},
Moon:{function:'emotional habits, instinctive responses, memory, and the ways care is given and received',question:'What helps me feel safe enough to respond rather than simply react?',practice:'Notice a recurring daily rhythm: what happens before you withdraw, seek company, become busy, or ask for reassurance? Try naming the need directly before judging the response.',cycle:'The Moon circles the zodiac in about 27.3 days. Its phase cycle relative to the Sun is about 29.5 days. A lunar return and a repeating Moon phase therefore occur on different schedules.',retro:'The geocentric Moon does not retrograde. Its speed varies, which is one reason an unknown birth time can change the Moon sign on a boundary day.',relationship:'Moon contacts in synastry can invite attention to comfort, familiarity, and emotional timing. Two people can share a sign and still need different forms of care; ask about lived experience.',work:'The Moon can be used to reflect on sustainable routines, the emotional atmosphere of a workplace, memory, and the conditions that allow concentrated effort.'},
Mercury:{function:'attention, language, learning, reasoning, and the exchange of information',question:'How do I check whether I have understood and been understood?',practice:'Try presenting the same idea in a short sentence, a concrete example, and a question. Different situations may need a different form of communication.',cycle:'Mercury remains relatively close to the Sun in geocentric longitude and completes several direct/retrograde cycles in a year. Its sign is normally the Sun’s sign or an adjacent sign.',retro:'Mercury retrograde is apparent geocentric backward motion. In interpretation it can be used as a prompt to review assumptions and communication, but it does not establish that a message, purchase, or journey will fail.',relationship:'Mercury contacts are especially useful when exploring differences in pace, wording, listening, and interpretation. A tense aspect can describe a productive debate when both people are able to clarify rather than compete.',work:'Consider research, writing, teaching, analysis, trade, and the everyday processes that turn information into shared understanding.'},
Venus:{function:'values, attraction, reciprocity, pleasure, and aesthetic appreciation',question:'What do I value, and how do my choices make those values visible?',practice:'List one kind of pleasure, one form of affection, and one agreement that feels nourishing. Ask whether they are chosen values or expectations inherited from somebody else.',cycle:'Venus alternates between morning-star and evening-star visibility and repeats a recognizable geocentric pattern over roughly eight years. Its retrograde periods occur about every 19 months.',retro:'Venus retrograde can symbolically frame a review of values, attraction, or reciprocity. It is not evidence that a relationship is destined to end or that beginning one is wrong.',relationship:'Venus speaks to how a person appreciates, relates, and negotiates values. Read it alongside the Moon’s needs, Mars’s desire, and the actual agreements between people.',work:'Venus can be relevant to design, art, collaboration, pricing, hospitality, negotiation, and whether the work’s values match the conditions in which it is done.'},
Mars:{function:'action, desire, assertion, conflict, and the ability to defend a boundary',question:'What am I pursuing, and can I state the aim directly?',practice:'Turn a recurring frustration into a specific request or boundary. Identify one action you can take without needing to control another person’s response.',cycle:'Mars takes roughly two years to move around the zodiac and has a retrograde period about every 26 months. It remains much longer in some signs when its apparent motion slows and reverses.',retro:'Mars retrograde is a change in apparent longitude direction, not a loss of physical energy. An astrological reading may explore reassessment of strategy, anger, or an aim rather than treating delay as inevitable.',relationship:'Mars can describe pursuit, desire, autonomy, and responses to disagreement. Venus–Mars contacts are one part of synastry; they do not establish consent, attraction, or relationship quality on their own.',work:'Consider initiative, competition, advocacy, decision-making, skilled physical effort, and how conflict is addressed when resources or priorities differ.'},
Jupiter:{function:'growth, belief, meaning, generosity, and the search for a wider perspective',question:'What would expand my understanding without outrunning my resources?',practice:'Choose an idea you believe strongly and seek a thoughtful account from a different perspective. Growth can mean a revised assumption as well as a larger opportunity.',cycle:'Jupiter takes about twelve years to travel around the zodiac, often spending around a year in a sign. It retrogrades for several months in many calendar years.',retro:'Jupiter retrograde may be interpreted as an inward review of beliefs, aims, or the meaning given to growth. It is not a measured reduction in luck or a guarantee that an opportunity disappears.',relationship:'Jupiter contacts can describe encouragement, shared meaning, or the feeling that possibility grows in another person’s company. Discuss whether encouragement is realistic and mutually welcome.',work:'Jupiter is often interpreted through education, publishing, law, travel, mentorship, and the judgment required to connect a broad vision to a real context.'},
Saturn:{function:'limits, time, structure, accountability, and commitments that develop through repeated effort',question:'Which responsibility is mine, and what support makes it sustainable?',practice:'Separate an important commitment from an inherited rule about what you must prove. Make the next step realistic, including enough time and resources to complete it.',cycle:'Saturn takes about 29.5 years to circle the zodiac. A Saturn return refers to its return to the natal longitude, with exact timing affected by retrograde passes.',retro:'Saturn retrograde can be a symbolic frame for examining an internal rule or rebuilding an external structure. It does not demonstrate that punishment, isolation, or failure is coming.',relationship:'Saturn contacts can be read through durability, responsibility, boundaries, and the different ways people experience obligation. Commitment works best when it is negotiated, rather than imposed by one person on the other.',work:'Reflect on mastery, administration, stewardship, realistic planning, standards, and the distinction between earned authority and an unquestioned hierarchy.'},
Uranus:{function:'innovation, disruption, freedom, and changes to a familiar arrangement',question:'What needs a genuinely different approach, and who will be affected by the change?',practice:'Try a small, reversible experiment before redesigning the whole system. Notice whether the change serves a need or primarily provides relief from boredom.',cycle:'Uranus takes about 84 years to circle the zodiac and spends roughly seven years in a sign. Its sign therefore describes a shared cohort context more than a uniquely personal trait.',retro:'Outer-planet retrogrades last many months and are shared by large numbers of people. A natal retrograde label should be read in the whole chart, rather than as a rare defining feature.',relationship:'Uranus contacts may be interpreted through autonomy, surprise, and changes in expectations. A need for space becomes easier to work with when agreements make room for both freedom and reliability.',work:'Useful questions concern experimentation, technology, reform, social networks, and which assumptions a working system makes about the people using it.'},
Neptune:{function:'imagination, ideals, receptivity, and experiences where boundaries become less clear',question:'What is an image, a hope, a shared feeling, or a fact that can be checked?',practice:'Give an imagined project a concrete container: a sketch, a recording, a deadline, or a written agreement. Clarity can protect a creative or compassionate intention.',cycle:'Neptune takes about 165 years to circle the zodiac, spending around fourteen years in a sign. Its natal house and aspects are often more individually specific than its sign.',retro:'Neptune retrograde is common across a large part of each year. Symbolic reflection may focus on ideals and assumptions, without claiming that the motion causes confusion or revelation.',relationship:'Neptune contacts can invite reflection on empathy, imagination, idealization, and unclear expectations. Check the difference between a felt connection and the other person’s actual availability or agreement.',work:'Neptune symbolism can be explored through art, film, music, imagery, collective ideals, and work where a compassionate aim needs a clear practical boundary.'},
Pluto:{function:'power, deep change, concentrated investment, and processes that are difficult to keep on the surface',question:'Where do I need more honest agency, and where am I trying to control what is not mine?',practice:'Identify a recurring pattern in which the apparent issue is smaller than what seems emotionally at stake. Focus on a choice or boundary you can own rather than an interpretation of somebody else’s hidden motive.',cycle:'Pluto takes about 248 years to orbit the Sun, with a highly variable time spent in each sign. Its sign is strongly generational; natal house and close aspects add personal context.',retro:'Pluto retrograde lasts several months in most years and is not rare. A retrograde symbol does not indicate that someone is more powerful, damaged, or destined for a particular life event.',relationship:'Pluto contacts can be discussed through intensity, investment, agency, and the handling of vulnerability. Astrological symbolism should never be used to excuse coercion or describe control as proof of love.',work:'Consider research, investigation, shared resources, restoration, complex institutional change, and explicit ethical boundaries where sensitive information or unequal power is involved.'}
};
export type HouseDepth={title:string;domain:string;topics:string;example:string;question:string;traditional:string};
export const houseDepth:HouseDepth[]=[
{title:'Identity & first impressions',domain:'your approach to beginnings, embodied presence, and personal agency',topics:'Appearance, self-presentation, vitality in traditional symbolism, and the ways you meet an unfamiliar setting. The Ascendant degree is an angle; the first whole-sign house is the entire sign containing it.',example:'Joining a new group and choosing how much to initiate, observe, or reveal.',question:'How do I begin, and what helps me inhabit my own choices?',traditional:'An angular house, traditionally connected with life and the native. Do not equate the first house with Aries: a house is a field of life, not a zodiac sign.'},
{title:'Resources & personal values',domain:'income, possessions, practical resources, and what you choose to maintain',topics:'Earning, spending, ownership, skills that can sustain a livelihood, and the relationship between resources and chosen priorities. Modern readings often add self-worth; it should not be reduced to financial success.',example:'Deciding whether a purchase supports a lasting priority or only a temporary impression.',question:'What do I need enough of, and what is already enough?',traditional:'A succedent house concerned with livelihood and movable possessions. Its ruler and condition are distinct from an automatic Venus or Taurus correspondence.'},
{title:'Communication & nearby life',domain:'everyday exchanges, local surroundings, siblings, and practical learning',topics:'Language, writing, short journeys, neighbors, everyday information, and the habits through which knowledge is exchanged. Learning here is situated in ordinary experience rather than being limited to formal study.',example:'Developing a clearer way to coordinate a shared household schedule.',question:'What do I repeatedly notice, say, and assume in daily life?',traditional:'A cadent house associated with siblings, journeys, and the Moon’s traditional joy. Houses should not simply be renamed after the matching sign number.'},
{title:'Home, roots & private life',domain:'home, ancestry, family foundations, and a private sense of belonging',topics:'Living arrangements, family narratives, land and property in traditional readings, and the conditions that allow you to return to yourself. The IC is an angle that can fall outside the fourth whole-sign house.',example:'Choosing which family practice to continue and which to change in your own home.',question:'What makes a place feel like a foundation rather than just an address?',traditional:'An angular house associated with parents, origins, land, and endings. Attribution to a particular parent varies by school and should be stated rather than assumed.'},
{title:'Creativity, play & pleasure',domain:'creative expression, recreation, romance, and what you make or bring into life',topics:'Art, performance, games, enjoyment, children in many traditional readings, and forms of authorship that carry personal investment. Pleasure has value even when it produces no achievement.',example:'Protecting a weekly time for music or play without requiring it to become a business.',question:'What would I make room for if enjoyment did not need to justify itself?',traditional:'A succedent house traditionally called Good Fortune and associated with Venus’s joy. It is broader than romance alone.'},
{title:'Daily work, care & routines',domain:'daily duties, service, maintenance, and the organization of practical effort',topics:'Everyday work conditions, habits, tasks that keep life running, and the distribution of care. Historical texts also connect this house to illness and servitude; a chart is not a medical diagnostic tool.',example:'Changing a recurring process so that needed work does not depend on one exhausted person.',question:'Which routine supports life, and which routine has become unnecessary labor?',traditional:'A cadent house with difficult associations in many ancient sources; modern psychological usage often emphasizes routines and service. These historical and modern frames are distinct.'},
{title:'Partnership & agreements',domain:'one-to-one relationships, collaboration, contracts, and direct encounters with another',topics:'Marriage, committed partnership, clients, opponents, and agreements where another person has a distinct voice. The Descendant angle marks the setting horizon; whole-sign house boundaries follow the rising sign.',example:'Making an explicit agreement about responsibilities in a shared project.',question:'What makes an agreement both mutual and honest?',traditional:'An angular house concerned with marriage and open opponents among other matters. Relationship outcomes cannot be established from an isolated house placement.'},
{title:'Shared resources & vulnerability',domain:'shared finances, debts, inheritances, obligations, and the experience of dependence',topics:'Joint assets, financial entanglements, what passes between generations, and questions around loss and trust. Modern interpretations often add intimacy and psychological transformation; these extend beyond the older financial and mortality themes.',example:'Clarifying how a joint expense will be handled before assumptions become resentment.',question:'What am I sharing, what do I owe, and what remains mine to choose?',traditional:'A succedent house historically concerned with death and the resources of others. Atlas does not use it to predict death or make alarming claims.'},
{title:'Belief, travel & higher learning',domain:'worldview, extended study, distant places, and frameworks that give experience meaning',topics:'Religion, philosophy, higher education, publishing, law, and journeys that take you beyond the familiar. The useful question is how beliefs are formed and revised, not whether a placement proves one belief true.',example:'Studying an unfamiliar tradition in its own terms before comparing it with your own.',question:'Which experience could enlarge or revise the story I tell about the world?',traditional:'A cadent house traditionally called God and associated with the Sun’s joy. Its relationship with the third house can frame different scales of knowing and travel.'},
{title:'Vocation & public life',domain:'vocation, public responsibility, recognition, and the contribution visible to a wider world',topics:'Work roles, reputation, authority, professional direction, and what people know you for. A vocation need not be a paid occupation. In whole-sign houses, the Midheaven can appear in another house and adds a separate emphasis.',example:'Choosing a role because its responsibilities fit your values, rather than only its title.',question:'What contribution am I prepared to become accountable for?',traditional:'An angular house associated with action, reputation, and office. Traditional attributions concerning parents vary; they are not universal statements about family roles.'},
{title:'Friends, community & hopes',domain:'friendship networks, collective aims, alliances, and hopes for what could develop',topics:'Groups, patrons in traditional texts, professional networks, mutual support, and the future made possible through association. Belonging can involve both finding a group and contributing to how the group works.',example:'Turning a private interest into a community project with shared decision-making.',question:'Who helps the future become possible, and what kind of community do I support?',traditional:'A succedent house traditionally called Good Spirit and associated with Jupiter’s joy. Friends and benefactors are central older themes.'},
{title:'Retreat, solitude & hidden matters',domain:'solitude, experiences outside public view, retreat, and patterns that are difficult to see directly',topics:'Private reflection, isolation, institutions, concealed circumstances, and what remains outside everyday attention. Modern readings may emphasize dreams or the unconscious. A placement does not prove a hidden enemy or a personal defect.',example:'Taking intentional quiet time and noticing whether it restores connection or prolongs avoidance.',question:'What becomes easier to notice when the usual noise settles?',traditional:'A cadent house traditionally called Bad Spirit and associated with Saturn’s joy. Historical difficult meanings should be contextualized rather than turned into a frightening personal prediction.'}
];
export function dignity(planet:string,sign:string){const rulers=signs.find(s=>s.name===sign)?.rulers||[];const ex:Record<string,string>={Sun:'Aries',Moon:'Taurus',Mercury:'Virgo',Venus:'Pisces',Mars:'Capricorn',Jupiter:'Cancer',Saturn:'Libra'};if(rulers[0]===planet&&ex[planet]===sign)return 'Traditional domicile and exaltation';if(rulers[0]===planet)return 'Traditional domicile';if(ex[planet]===sign)return 'Traditional exaltation';const i=signs.findIndex(s=>s.name===sign);if(signs[(i+6)%12]?.rulers[0]===planet&&ex[planet]===signs[(i+6)%12]?.name)return 'Traditional detriment and fall';if(signs[(i+6)%12]?.rulers[0]===planet)return 'Traditional detriment';if(ex[planet]===signs[(i+6)%12]?.name)return 'Traditional fall';if(rulers.slice(1).includes(planet))return 'Modern rulership';return ['Uranus','Neptune','Pluto'].includes(planet)?'No universal traditional dignity scheme':'No domicile, exaltation, detriment, or fall';}
const outerStyle:Record<string,string>={Jupiter:'growth and beliefs',Saturn:'boundaries and commitments',Uranus:'innovation and freedom',Neptune:'imagination and ideals',Pluto:'power and deep change'};
export function placementText(planet:string,sign:string){const s=signs.find(s=>s.name===sign)!;const d=signDepth[sign];if(planet==='North Node'||planet==='South Node')return `${planet} in ${sign} places one end of the lunar-node axis in a ${s.modality.toLowerCase()} ${s.element.toLowerCase()} sign. The nodes are orbital intersections, not planets. Modern Western readings often discuss familiar patterns and development across this axis, while Jyotish uses a different Rahu–Ketu framework. Read both ends, their rulers, and the chosen tradition; do not treat this point as proof of a factual past-life story. Atlas uses an approximate mean-node model.`;return d.placements[planet]||`${planet} in ${sign} gives ${outerStyle[planet]||'this chart function'} a ${s.modality.toLowerCase()} ${s.element.toLowerCase()} expression. ${d.motivation.split('. ').slice(0,2).join('. ')}. ${planet==='Saturn'?'The constructive question is how this sign learns patience and builds a boundary without losing access to its strengths.':planet==='Jupiter'?'The constructive question is how enthusiasm, learning, and perspective can expand this sign’s resources without assuming that more is always better.':planet==='Uranus'?'Ask which conventions this sign is willing to question, and what would make a new approach genuinely useful to the people affected.':planet==='Neptune'?'Explore the difference between an inspiring ideal and an assumption that needs to be checked against experience.':'Consider where emotional investment becomes concentrated, and how agency can be preserved without needing to control another person.'} ${['Uranus','Neptune','Pluto'].includes(planet)?'Because this is a slow-moving planet, the sign is shared with a broad cohort; its house and close aspects make the reading more personally specific.':''}`;}
export function housePlacementText(planet:string,house:number){if(planet==='Ascendant')return 'The rising sign establishes House 1 in the whole-sign system. The Ascendant degree itself is the precise eastern horizon intersection; follow the sign’s ruler to its own sign, house, and aspects to continue the reading.';const p=planetDepth[planet];const h=houseDepth[house-1];return `${planet} in House ${house} brings ${p?.function||'this chart function'} into ${h.domain}. The sign describes the style; the house identifies the field in which that style is being used. For example: ${h.example.charAt(0).toLowerCase()+h.example.slice(1)} Read the house’s ruler and the planet’s aspects before treating a single placement as the whole explanation.`;}
export const aspectMeaning:Record<string,{verb:string;meaning:string;practice:string}>={Conjunction:{verb:'combine',meaning:'A conjunction concentrates two functions in the same part of the zodiac. They may reinforce, blend with, or compete for expression. Whether the combination feels easy depends on the planets, context, and how the person works with both needs.',practice:'Name what each function needs before expecting a single action to satisfy both. A combined strength can still need an internal boundary.'},Sextile:{verb:'offer cooperation between',meaning:'A sextile describes a potentially cooperative relationship. Unlike a guarantee of effortless success, it is often read as an opening that becomes more useful through participation and choice.',practice:'Look for a small action that allows the two functions to support each other rather than waiting for the opportunity to use itself.'},Square:{verb:'create friction between',meaning:'A square brings two functions into an angular relationship often interpreted through competing demands. The tension can be productive when both sides are acknowledged instead of requiring one to disappear.',practice:'Choose a concrete situation and ask what would give each need some room. The aim is an arrangement that can be revised, not a verdict about a good or bad chart.'},Trine:{verb:'create a fluent link between',meaning:'A trine is commonly associated with ease, familiarity, or a flow of resources. Ease can become a skill when used deliberately; it can also remain an unexamined habit.',practice:'Use a natural strength toward a chosen aim. Notice what already works and what would help that resource become available to others.'},Opposition:{verb:'bring a polarity between',meaning:'An opposition places two functions across a polarity. It may be experienced through alternating priorities or an encounter with another person, inviting a perspective that can hold both sides.',practice:'Describe each side without immediately defending it. Ask what a flexible balance would look like in the current situation rather than demanding permanent symmetry.'}};
const pairNotes:Record<string,string>={
'Moon|Sun':'Purpose and emotional need are related but not identical. A choice can be meaningful to identity while requiring additional care or adjustment in daily life.',
'Mercury|Moon':'Words and feelings may work at different speeds. Clarifying whether a conversation is for understanding, comfort, or a decision can prevent a helpful explanation from feeling dismissive.',
'Mars|Moon':'Action and emotional responses can become closely linked. Distinguish a boundary that needs expression from an impulse that would benefit from a pause.',
'Moon|Venus':'Comfort and affection are not always the same language. Discuss which gestures are pleasant and which specifically help someone feel cared for.',
'Moon|Saturn':'Emotional safety meets duty and limitation. Reliability can offer care, while a demanding internal rule can make receiving support feel difficult.',
'Moon|Pluto':'Feeling and concentrated emotional investment meet here. Explore trust and vulnerability without treating suspicion or control as proof of insight.',
'Mars|Venus':'Values and attraction meet pursuit and assertion. Talk about both desire and consent; a symbolic connection cannot establish either person’s actual wishes.',
'Saturn|Venus':'Affection and commitment meet boundaries and responsibility. A dependable agreement can support pleasure; obligation without reciprocity can crowd it out.',
'Neptune|Venus':'Affection and imagination can enrich one another, while idealization can obscure an unmet need. Check that the hoped-for relationship matches the agreement being lived.',
'Pluto|Venus':'Connection and deep investment can feel consequential. Mutual agency, honest boundaries, and room for different needs are more useful than labeling intensity as destiny.',
'Mercury|Saturn':'Thinking and communication meet standards, structure, or inhibition. Precision can be a strength when there is also permission to ask an unfinished question.',
'Mars|Mercury':'Language and assertion can sharpen one another. A forceful point becomes more useful when clarity is separated from the wish to win the exchange.',
'Jupiter|Mercury':'Details and a larger framework meet. An idea benefits from both imagination about possibility and the checks that make it accurate enough to use.',
'Mercury|Neptune':'Reasoning and imagination meet. Images or intuition may be valuable starting points, with notes and explicit confirmation helping when accuracy matters.',
'Mars|Saturn':'The urge to act meets limits, patience, or resistance. A realistic sequence can make disciplined action possible without treating every pause as defeat.',
'Jupiter|Saturn':'Expansion and consolidation meet. A sound plan can include both possibility and a practical account of the resources required.',
'Saturn|Sun':'Identity and purpose meet responsibility and limits. A lasting commitment is different from a rule that makes personal worth depend on never making a mistake.',
'Neptune|Sun':'Identity meets ideals and imagination. A creative or compassionate purpose becomes more sustainable when it has a clear boundary and a concrete form.',
'Pluto|Sun':'Purpose meets questions of power and deep investment. Consider what can be changed through your own choices and what cannot appropriately be controlled.',
'Sun|Uranus':'Identity meets autonomy and change. Originality becomes more useful when the freedom to differ is connected to a chosen contribution.',
'Mars|Uranus':'Action meets rapid change and the wish for autonomy. A reversible experiment may be more informative than an all-or-nothing break with the current arrangement.'
};
export function aspectReading(a:string,b:string,name:string,synastry=false){const def=aspectMeaning[name]||aspectMeaning.Conjunction;const pair=pairNotes[[a,b].sort().join('|')]||`${a} describes ${planetDepth[a]?.function||'one chart function'}, while ${b} describes ${planetDepth[b]?.function||'another function'}. Consider both motives before assigning a single meaning to the contact.`;return {title:`${a} ${name.toLowerCase()} ${b}`,meaning:def.meaning,connection:pair,practice:synastry?`In synastry, these functions belong to two different people. Ask how the interaction feels to each person, rather than assuming they experience it identically. ${def.practice}`:def.practice};}
export function synthesizePlacement(pos:Position,all:Position[],asp:Aspect[]){const s=zodiac(pos.lon);const linked=asp.filter(a=>a.a===pos.name||a.b===pos.name).slice(0,3);return {title:`${pos.name} in ${s.name}${pos.house?`, House ${pos.house}`:''}`,position:`${degree(pos.lon)} ${s.name}${pos.retro?' · retrograde':''}${pos.uncertain?' · sign may change with birth time':''}`,overview:placementText(pos.name,s.name),house:pos.house?housePlacementText(pos.name,pos.house):'A house is not assigned because the birth time is unknown. The sign and planetary aspects are sampled at local noon.',aspects:linked.map(a=>({...a,...aspectReading(a.a,a.b,a.name)}))};}
